'use client';
import { collection, getDocs } from 'firebase/firestore';
import { useEffect, useMemo, useState } from 'react';
import { db } from '@/lib/firebase';

type Product = { id: string; data: Record<string, any> };
type Promoter = { id: string; name: string; whatsapp: string; area: string; ref: string };
type Slot = { promoterId: string; promoterName: string; day: number; productId: string };
type Poster = { dataUrl: string; fileName: string; url: string };

const W = 1080, H = 1350;
const WEBSITE = 'www.spotc.in';
const PHONE = '+91 80720 98066';
const AREAS = 'Karamadai • Teacher Colony • EB Colony • Gandhinagar';
const ADDRESS = 'SPOTC TECHNOLOGIES, #41-1, Kembe Gowder Colony 1st Street, Near EB Colony Bus Stop, Karamadai, Coimbatore - 641104, Tamil Nadu, India';
const PROMOTER_STORAGE_KEY = 'spotc_homemaker_promoters_v2';

const SPOTC_LOGO = 'data:image/webp;base64,';

function textValue(value: unknown): string { return String(value ?? '').trim(); }
function moneyValue(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const cleaned = String(value ?? '').replace(/[^0-9.]/g, '');
  return Number(cleaned) || 0;
}
function titleOf(d: Record<string, any>): string { return textValue(d.title || d.product_name || 'Product'); }
function imageOf(d: Record<string, any>): string {
  const a = Array.isArray(d.images) ? d.images : [];
  return textValue(d.thumbnail_url || d.thumbnailUrl || d.web_thumbnail_url || d.card_image_url || d.product_thumbnail || a[0] || d.image || d.image_url || d.product_image_url || d.studio_image_url || '');
}
function sellingPriceOf(d: Record<string, any>): number {
  return moneyValue(d.selling_price ?? d.price ?? d.mrp ?? d.old_price ?? 0);
}
function offerPriceOf(d: Record<string, any>): number {
  const offer = moneyValue(d.offer_price);
  const selling = sellingPriceOf(d);
  return offer > 0 && (selling <= 0 || offer < selling) ? offer : 0;
}
function priceOf(d: Record<string, any>): number { return offerPriceOf(d) || sellingPriceOf(d); }
function mrpOf(d: Record<string, any>): number { return moneyValue(d.mrp ?? d.old_price ?? d.original_price ?? 0); }
function discountOf(d: Record<string, any>): string {
  const m = mrpOf(d), p = priceOf(d);
  if (m > p && p > 0) return `${Math.round(((m - p) / m) * 100)}% OFF`;
  const stored = textValue(d.discount || d.discount_percent);
  return stored && stored !== '0' ? (stored.includes('%') ? stored : `${stored}% OFF`) : '';
}
function slug(v: string): string { return v.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'promoter'; }
function safe(v: string): string { return v.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 55) || 'spotc-promotion'; }
function trackedUrl(id: string, ref: string): string { return `https://${WEBSITE}/product/${encodeURIComponent(id)}?ref=${encodeURIComponent(ref)}`; }
function path(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  const q = Math.min(r, w / 2, h / 2); ctx.beginPath(); ctx.moveTo(x + q, y); ctx.arcTo(x + w, y, x + w, y + h, q); ctx.arcTo(x + w, y + h, x, y + h, q); ctx.arcTo(x, y + h, x, y, q); ctx.arcTo(x, y, x + w, y, q); ctx.closePath();
}
function box(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number, fill: string, stroke = '') { path(ctx, x, y, w, h, r); ctx.fillStyle = fill; ctx.fill(); if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 2; ctx.stroke(); } }
function wrap(ctx: CanvasRenderingContext2D, t: string, x: number, y: number, max: number, line: number, maxLines = 2) {
  const words = t.split(/\s+/).filter(Boolean), lines: string[] = []; let cur = '';
  for (const word of words) { const test = cur ? `${cur} ${word}` : word; if (ctx.measureText(test).width <= max) cur = test; else { if (cur) lines.push(cur); cur = word; if (lines.length === maxLines - 1) break; } }
  if (cur && lines.length < maxLines) lines.push(cur);
  if (lines.length === maxLines && lines.join(' ').length < words.join(' ').length) { let s = lines[maxLines - 1]; while (ctx.measureText(s + '…').width > max && s) s = s.slice(0, -1); lines[maxLines - 1] = s + '…'; }
  lines.forEach((v, i) => ctx.fillText(v, x, y + i * line)); return y + lines.length * line;
}
function contain(ctx: CanvasRenderingContext2D, img: HTMLImageElement, x: number, y: number, w: number, h: number) {
  const sw = img.naturalWidth || img.width, sh = img.naturalHeight || img.height, s = Math.min(w / sw, h / sh); ctx.drawImage(img, x + (w - sw * s) / 2, y + (h - sh * s) / 2, sw * s, sh * s);
}
async function loadImage(src: string) { return await new Promise<HTMLImageElement>((resolve, reject) => { const i = new Image(); i.onload = () => resolve(i); i.onerror = () => reject(new Error('Image could not be loaded')); i.src = src; }); }
async function productImage(url: string) {
  let r: Response | null = null; try { r = await fetch(url, { mode: 'cors', cache: 'no-store' }); } catch {}
  if (!r?.ok) r = await fetch(`/api/admin/image-proxy?url=${encodeURIComponent(url)}`, { cache: 'no-store' });
  if (!r.ok) throw new Error(`Product image download failed (${r.status})`);
  const u = URL.createObjectURL(await r.blob()); try { return await loadImage(u); } finally { setTimeout(() => URL.revokeObjectURL(u), 1000); }
}
async function makePoster(p: Product, promoter: Promoter, day: number): Promise<Poster> {
  const src = imageOf(p.data); if (!src) throw new Error('Product has no image');
  const [img, logo] = await Promise.all([productImage(src), loadImage(SPOTC_LOGO)]);
  const c = document.createElement('canvas'); c.width = W; c.height = H; const ctx = c.getContext('2d'); if (!ctx) throw new Error('Canvas unavailable');
  const title = titleOf(p.data), price = priceOf(p.data), mrp = mrpOf(p.data), off = discountOf(p.data);
  if (price <= 0) throw new Error(`Price missing for “${title}”. Please check the product price in Products.`);

  const bg = ctx.createLinearGradient(0, 0, W, H); bg.addColorStop(0, '#fffaf6'); bg.addColorStop(0.58, '#ffffff'); bg.addColorStop(1, '#fff4f8'); ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
  contain(ctx, logo, 54, 38, 310, 88);
  box(ctx, 772, 34, 254, 82, 28, '#ed0a4f'); ctx.fillStyle = '#ffd21f'; ctx.font = '900 34px Arial'; ctx.fillText('15 MIN', 815, 69); ctx.fillStyle = '#fff'; ctx.font = '900 21px Arial'; ctx.fillText('DELIVERY', 815, 97);
  ctx.fillStyle = '#6b7280'; ctx.font = '700 18px Arial'; ctx.fillText("TODAY'S LOCAL PICK", 56, 153);
  ctx.textAlign = 'right'; ctx.fillStyle = '#10244c'; ctx.font = '800 18px Arial'; ctx.fillText(`DAY ${day} • ${promoter.name}`, 1024, 153); ctx.textAlign = 'left';

  box(ctx, 46, 181, 988, 590, 34, '#ffffff', '#f0e2e6');
  ctx.save(); ctx.shadowColor = 'rgba(16,36,76,.12)'; ctx.shadowBlur = 30; ctx.shadowOffsetY = 12; box(ctx, 74, 208, 932, 536, 26, '#ffffff'); ctx.restore();
  contain(ctx, img, 100, 230, 880, 492);

  ctx.textAlign = 'center'; ctx.fillStyle = '#10244c'; ctx.font = '900 34px Arial'; wrap(ctx, title, 540, 825, 900, 42, 2); ctx.textAlign = 'left';
  box(ctx, 54, 905, 972, 134, 28, '#ffffff', '#eadfe4');
  ctx.fillStyle = '#ed0a4f'; ctx.font = '900 68px Arial'; ctx.fillText(`₹${price.toLocaleString('en-IN')}`, 84, 987);
  if (mrp > price) { ctx.fillStyle = '#6b7280'; ctx.font = '700 23px Arial'; ctx.fillText(`MRP ₹${mrp.toLocaleString('en-IN')}`, 390, 950); ctx.strokeStyle = '#6b7280'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(390, 942); ctx.lineTo(520, 942); ctx.stroke(); }
  if (off) { box(ctx, 552, 920, 176, 50, 18, '#ffe6ef'); ctx.fillStyle = '#ed0a4f'; ctx.font = '900 22px Arial'; ctx.fillText(off, 576, 953); }
  box(ctx, 752, 920, 240, 56, 18, '#10244c'); ctx.fillStyle = '#fff'; ctx.font = '900 19px Arial'; ctx.fillText('CASH ON DELIVERY', 773, 955);

  ctx.fillStyle = '#6b7280'; ctx.font = '700 17px Arial'; ctx.fillText('LOCAL DELIVERY', 62, 1082); ctx.fillStyle = '#10244c'; ctx.font = '800 20px Arial'; ctx.fillText(AREAS, 62, 1112);
  box(ctx, 54, 1150, 972, 82, 24, '#ed0a4f'); ctx.fillStyle = '#fff'; ctx.font = '900 34px Arial'; ctx.fillText('ORDER NOW', 88, 1202); ctx.fillStyle = '#ffd21f'; ctx.textAlign = 'right'; ctx.font = '900 27px Arial'; ctx.fillText(WEBSITE, 995, 1202); ctx.textAlign = 'left';
  ctx.fillStyle = '#10244c'; ctx.fillRect(0, 1254, W, 96); ctx.fillStyle = '#fff'; ctx.font = '800 16px Arial'; ctx.fillText('SPOTC TECHNOLOGIES • KARAMADAI', 48, 1280); ctx.font = '600 12px Arial'; wrap(ctx, ADDRESS, 48, 1304, 690, 16, 2); ctx.textAlign = 'right'; ctx.font = '800 15px Arial'; ctx.fillText(`WhatsApp ${promoter.whatsapp || PHONE}`, 1028, 1280); ctx.font = '600 12px Arial'; ctx.fillText('Tap the product link to shop', 1028, 1305); ctx.textAlign = 'left';
  return { dataUrl: c.toDataURL('image/png'), fileName: `${safe(promoter.name)}-day-${day}-${safe(title)}.png`, url: trackedUrl(p.id, promoter.ref) };
}

export default function HomemakerPromotionsPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [promoters, setPromoters] = useState<Promoter[]>([]);
  const [name, setName] = useState('');
  const [whatsapp, setWhatsapp] = useState('');
  const [area, setArea] = useState('Karamadai');
  const [editingId, setEditingId] = useState('');
  const [day, setDay] = useState(1);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [posters, setPosters] = useState<Record<string, Poster>>({});
  const [busy, setBusy] = useState('');
  const [message, setMessage] = useState('Loading…');
  const [preview, setPreview] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(PROMOTER_STORAGE_KEY);
      if (raw) setPromoters(JSON.parse(raw));
    } catch {}
  }, []);

  useEffect(() => {
    try { localStorage.setItem(PROMOTER_STORAGE_KEY, JSON.stringify(promoters)); } catch {}
  }, [promoters]);

  useEffect(() => {
    (async () => {
      try {
        const s = await getDocs(collection(db, 'BusinessProducts'));
        const list = s.docs
          .map((d) => ({ id: d.id, data: d.data() }))
          .filter((p) => p.data.isActive !== false && imageOf(p.data));
        setProducts(list);
        setMessage(`${list.length} products loaded.`);
      } catch (e) {
        setMessage(e instanceof Error ? e.message : 'Could not load products.');
      } finally { setLoading(false); }
    })();
  }, []);

  const current = useMemo(() => slots.filter((s) => s.day === day), [slots, day]);

  function resetForm() { setName(''); setWhatsapp(''); setArea('Karamadai'); setEditingId(''); }

  function savePromoter() {
    const cleanName = name.trim();
    if (!cleanName) { setMessage('Promoter name is required.'); return; }
    if (promoters.length >= 25 && !editingId) { setMessage('Maximum 25 promoters allowed.'); return; }
    if (editingId) {
      setPromoters((prev) => prev.map((p) => p.id === editingId ? { ...p, name: cleanName, whatsapp: whatsapp.trim(), area: area.trim() || 'Karamadai', ref: slug(cleanName) } : p));
      setMessage(`${cleanName} updated.`);
    } else {
      const base = slug(cleanName); const ref = promoters.some((p) => p.ref === base) ? `${base}-${promoters.length + 1}` : base;
      setPromoters((prev) => [...prev, { id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, name: cleanName, whatsapp: whatsapp.trim(), area: area.trim() || 'Karamadai', ref }]);
      setMessage(`${cleanName} added.`);
    }
    resetForm();
    setSlots([]); setPosters({});
  }

  function editPromoter(p: Promoter) { setEditingId(p.id); setName(p.name); setWhatsapp(p.whatsapp); setArea(p.area); }
  function removePromoter(id: string) { setPromoters((prev) => prev.filter((p) => p.id !== id)); setSlots([]); setPosters({}); if (editingId === id) resetForm(); }

  function createAssignments() {
    if (!products.length) { setMessage('Products are still loading.'); return; }
    if (!promoters.length) { setMessage('Add at least one promoter first.'); return; }
    if (products.length < promoters.length * 7) { setMessage(`You have ${products.length} usable products but need at least ${promoters.length * 7} for 7 unique products per promoter.`); return; }
    const next: Slot[] = [];
    for (let d = 1; d <= 7; d++) {
      for (let i = 0; i < promoters.length; i++) {
        const productIndex = (d - 1) * promoters.length + i;
        const p = promoters[i];
        next.push({ promoterId: p.id, promoterName: p.name, day: d, productId: products[productIndex].id });
      }
    }
    setSlots(next); setPosters({}); setDay(1); setMessage(`${next.length} promotion slots created for ${promoters.length} promoter${promoters.length === 1 ? '' : 's'}.`);
  }

  function productFor(s: Slot) { return products.find((p) => p.id === s.productId); }
  function promoterFor(s: Slot) { return promoters.find((p) => p.id === s.promoterId); }

  async function generate(s: Slot) {
    const key = `${s.day}::${s.promoterId}`; const p = productFor(s); const promoter = promoterFor(s);
    if (!p || !promoter) return;
    setBusy(key);
    try { const poster = await makePoster(p, promoter, s.day); setPosters((v) => ({ ...v, [key]: poster })); setPreview(key); setMessage('Professional 1080 × 1350 share image generated.'); }
    catch (e) { setMessage(e instanceof Error ? e.message : 'Poster generation failed.'); }
    finally { setBusy(''); }
  }

  function download(k: string) { const p = posters[k]; if (!p) return; const a = document.createElement('a'); a.href = p.dataUrl; a.download = p.fileName; a.click(); }
  async function copyLink(k: string) { const p = posters[k]; if (!p) return; await navigator.clipboard.writeText(p.url); setMessage('Tracked product link copied.'); }

  return (
    <main style={{ minHeight: '100vh', background: '#f5f6fa', padding: 24, fontFamily: 'Arial,sans-serif', color: '#17233c' }}>
      <div style={{ maxWidth: 1480, margin: '0 auto' }}>
        <div style={{ background: '#fff', borderRadius: 20, padding: 24, boxShadow: '0 8px 30px rgba(16,36,76,.08)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 20, alignItems: 'flex-start', flexWrap: 'wrap' }}>
            <div><div style={{ fontSize: 30, fontWeight: 900 }}>SPOTC Homemaker Promotions</div><div style={{ marginTop: 7, color: '#687386' }}>{promoters.length} promoter{promoters.length === 1 ? '' : 's'} × 7 days × different products • professional WhatsApp Status images</div></div>
            <div style={{ padding: '10px 16px', borderRadius: 999, background: '#fff0f5', color: '#ed0a4f', fontWeight: 900 }}>{products.length} products ready</div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '390px 1fr', gap: 22, marginTop: 24 }}>
            <section style={{ border: '1px solid #e3e7ee', borderRadius: 16, padding: 18 }}>
              <div style={{ fontWeight: 900, fontSize: 19 }}>1. Promoters</div>
              <div style={{ fontSize: 13, color: '#687386', margin: '6px 0 14px' }}>Add only the promoters you have now. Maximum 25.</div>
              <div style={{ display: 'grid', gap: 8 }}>
                <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Promoter name *" style={{ padding: 12, border: '1px solid #ccd3df', borderRadius: 10, fontSize: 14 }} />
                <input value={whatsapp} onChange={(e) => setWhatsapp(e.target.value)} placeholder="WhatsApp number (optional)" style={{ padding: 12, border: '1px solid #ccd3df', borderRadius: 10, fontSize: 14 }} />
                <input value={area} onChange={(e) => setArea(e.target.value)} placeholder="Area" style={{ padding: 12, border: '1px solid #ccd3df', borderRadius: 10, fontSize: 14 }} />
                <div style={{ display: 'flex', gap: 8 }}><button onClick={savePromoter} style={{ flex: 1, padding: 12, border: 0, borderRadius: 10, background: '#ed0a4f', color: '#fff', fontWeight: 900 }}>{editingId ? 'Update Promoter' : 'Add Promoter'}</button>{editingId && <button onClick={resetForm} style={{ padding: '12px 14px', border: '1px solid #ccd3df', borderRadius: 10, background: '#fff', fontWeight: 800 }}>Cancel</button>}</div>
              </div>
              <div style={{ marginTop: 16, display: 'grid', gap: 8 }}>
                {promoters.length === 0 ? <div style={{ padding: 16, borderRadius: 12, background: '#f7f8fb', color: '#687386', fontSize: 13 }}>No promoters added yet.</div> : promoters.map((p, i) => (
                  <div key={p.id} style={{ display: 'grid', gridTemplateColumns: '30px 1fr auto', gap: 8, alignItems: 'center', padding: 10, border: '1px solid #e5e8ee', borderRadius: 11 }}>
                    <b style={{ color: '#ed0a4f' }}>{i + 1}</b><div><div style={{ fontWeight: 900 }}>{p.name}</div><div style={{ fontSize: 11, color: '#687386' }}>{p.area} • ref={p.ref}</div></div><div style={{ display: 'flex', gap: 4 }}><button onClick={() => editPromoter(p)} style={{ border: 0, background: '#eef2f8', borderRadius: 7, padding: '6px 8px', fontWeight: 800 }}>Edit</button><button onClick={() => removePromoter(p.id)} style={{ border: 0, background: '#fff0f2', color: '#c62845', borderRadius: 7, padding: '6px 8px', fontWeight: 800 }}>×</button></div>
                  </div>
                ))}
              </div>
              <button onClick={createAssignments} disabled={loading || !products.length || !promoters.length} style={{ marginTop: 14, width: '100%', padding: 14, border: 0, borderRadius: 12, background: '#10244c', color: '#fff', fontWeight: 900, fontSize: 15 }}>Create 7-Day Campaign</button>
              <div style={{ marginTop: 10, fontSize: 12, color: '#687386' }}>Example: 3 promoters = 21 promotion assignments.</div>
            </section>

            <section>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}><div style={{ fontWeight: 900, fontSize: 19 }}>2. Daily Promotions</div><div style={{ display: 'flex', gap: 6 }}>{[1,2,3,4,5,6,7].map((d) => <button key={d} onClick={() => setDay(d)} style={{ padding: '8px 13px', borderRadius: 999, border: '1px solid #ddd', background: day === d ? '#10244c' : '#fff', color: day === d ? '#fff' : '#333', fontWeight: 800 }}>Day {d}</button>)}</div></div>
              {slots.length === 0 ? <div style={{ background: '#fff', border: '1px dashed #c8ced8', borderRadius: 16, padding: 50, textAlign: 'center', color: '#687386' }}>Add your promoters, then click <b>Create 7-Day Campaign</b>.</div> : <div style={{ display: 'grid', gap: 10 }}>{current.map((s, i) => { const p = productFor(s); const promoter = promoterFor(s); const key = `${s.day}::${s.promoterId}`; const poster = posters[key]; return <div key={key} style={{ display: 'grid', gridTemplateColumns: '38px 150px minmax(240px,1fr) auto', gap: 12, alignItems: 'center', background: '#fff', border: '1px solid #e3e7ee', borderRadius: 14, padding: 12 }}><div style={{ fontWeight: 900, color: '#ed0a4f' }}>#{i + 1}</div><div><div style={{ fontWeight: 900 }}>{s.promoterName}</div><div style={{ fontSize: 11, color: '#687386' }}>{promoter?.area || ''}</div></div><div><div style={{ fontWeight: 800 }}>{p ? titleOf(p.data) : 'Missing product'}</div><div style={{ fontSize: 12, color: '#687386', marginTop: 3 }}>{p ? `₹${priceOf(p.data).toLocaleString('en-IN')} • ref=${promoter?.ref || slug(s.promoterName)}` : ''}</div></div><div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', justifyContent: 'flex-end' }}><button onClick={() => void generate(s)} disabled={busy === key || !p || !promoter} style={{ padding: '9px 12px', borderRadius: 9, border: 0, background: '#10244c', color: '#fff', fontWeight: 800 }}>{busy === key ? 'Generating…' : poster ? 'Regenerate' : 'Generate image'}</button><button onClick={() => setPreview(key)} disabled={!poster} style={{ padding: '9px 12px', borderRadius: 9, border: '1px solid #ccd3df', background: '#fff', fontWeight: 800 }}>Preview</button><button onClick={() => void copyLink(key)} disabled={!poster} style={{ padding: '9px 12px', borderRadius: 9, border: '1px solid #ccd3df', background: '#fff', fontWeight: 800 }}>Copy link</button><button onClick={() => download(key)} disabled={!poster} style={{ padding: '9px 12px', border: 0, borderRadius: 9, background: '#16a05d', color: '#fff', fontWeight: 800 }}>Download</button></div></div>; })}</div>}
              <div style={{ marginTop: 16, padding: 14, borderRadius: 12, background: '#fff8e8', color: '#6a4a00', fontSize: 13 }}><b>Workflow:</b> promoter → assigned product → professional 1080×1350 image → tracked product link → promoter posts to WhatsApp Status.</div>
            </section>
          </div>
          {message && <div style={{ marginTop: 18, padding: 12, borderRadius: 10, background: '#f0f4fa', fontSize: 13 }}>{message}</div>}
        </div>
      </div>

      {preview && posters[preview] && <div onMouseDown={(e) => { if (e.target === e.currentTarget) setPreview(''); }} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.72)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20, zIndex: 50 }}><div style={{ background: '#fff', borderRadius: 18, padding: 14, maxHeight: '95vh', overflow: 'auto', maxWidth: 650 }}><img src={posters[preview].dataUrl} alt="SPOTC professional promotion" style={{ display: 'block', width: '100%', height: 'auto', borderRadius: 12 }} /><div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 10 }}><button onClick={() => void copyLink(preview)} style={{ padding: '10px 14px', borderRadius: 9, border: '1px solid #ccd3df', background: '#fff' }}>Copy tracked link</button><button onClick={() => download(preview)} style={{ padding: '10px 14px', border: 0, borderRadius: 9, background: '#16a05d', color: '#fff', fontWeight: 800 }}>Download PNG</button><button onClick={() => setPreview('')} style={{ padding: '10px 14px', border: 0, borderRadius: 9, background: '#10244c', color: '#fff', fontWeight: 800 }}>Close</button></div></div></div>}
    </main>
  );
}
